-- GENERATED by `wfj generate` from data/gossip/gossip-89.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["890b5349adcd0d1c"] = { "Mostrerei al mio signore l'orecchio della bestia e mi attribuirei la sua uccisione, tenendo la ricompensa per me. È sbagliato attribuirsi un'impresa che in realtà ha compiuto qualcun altro.", "." },
  ["891601122843f77b"] = { "Komak! Giuro che avrò i soldi! Dammi solo un po' di tempo!", "." },
  ["89187474ee0b87af"] = { "Il Dun Baldar South Bunker è stato conquistato dall'⟦Alliance=Alleanza⟧!", "." },
  ["89194605740d7957"] = { "Incredibile! Non ho mai parlato con un fantasma. Voglio imparare!", "." },
  ["89242f2e4419d3ec"] = { "Un libro scritto da un goblin sulle vittorie militari degli gnomi... e tutte le pagine sono bianche. C'era da aspettarselo.", "." },
  ["8926f01b4820413d"] = { "Ahhh, giusto in tempo! Mi brontolava forte lo stomaco.", "." },
  ["8926f2f875be6e3a"] = { "Un fabbro? No, l'ultimo che avevamo è ridiventato uno di quei servi del Flagello senza cervello. Ce n'è uno a ⟦Undercity=Sepulcra⟧, però, a sud del villaggio. ⟦Undercity=Sepulcra⟧ si trova sotto le ⟦Ruins of Lordaeron=Rovine di Lordaeron⟧: nome azzeccato, eh? Prendi gli ascensori in fondo alle rovine e poi parla con uno degli Undercity Guardian. Sapranno indicarti la strada giusta.", "." },
  ["892b7f6441a348a9"] = { "Vuoi imparare a usare una nuova arma? Cerca Sayoc e Hanashi dentro Arms of Legend, nella ⟦Valley of Honor=Valle dell'Onore⟧.", "." },
  ["892e2470c14037a4"] = { "Voglio che dimostriate entrambi le tecniche che vi ho insegnato, a beneficio degli allievi più giovani qui presenti. Pronti... cominciate!", "." },
  ["89336859717361b4"] = { "È fatta. Il totem è pronto.", "." },
  ["8933fb3c69c10bfa"] = { "Arrivano. Cerca di non farti ammazzare, giovane.", "." },
  ["89389d7c4ac0481d"] = { "%s erompe dal terreno!", "." },
  ["8938bb1fc3f27b3d"] = { "Ho distrutto le mie armi di Azsharite! Mi serve il tuo aiuto per sconfiggere la triade del potere.", "." },
  ["893a1ac17cab818e"] = { "Va' in fretta... <coff coff> Trova... <coff> Ryedol...", "." },
  ["8941b76aa793224c"] = { "Voi così piccoli e gracili... voi no fare buoni servi per Kormok!", "." },
  ["89422aa45650305d"] = { "L'ora della nostra vendetta è giunta! Che l'oscurità regni nel cuore dei nostri nemici!", "." },
  ["89470707bbacada5"] = { "%s prepara lo Shattered Salute! *ATTENZIONE!*", "." },
  ["894e010f6b140893"] = { "Thorfin Stoneshield è venuto fin qui da ⟦Ironforge=Forgiardente⟧ per offrirci la sua esperienza nella caccia. Se non ti dispiace respirare l'aria piena di fumo del Dwarven District, lo troverai a casa sua, nella zona nord-est del distretto.", "." },
  ["89582086aa735f18"] = { "Ti do il benvenuto al Lion's Pride Inn. Fai come se fossi a casa tua!", "." },
  ["8961ca8934e85fba"] = { "Ce n'è uno a Orgrimmar. Va' a nord e parla con uno dei loro grunt.", "." },
  ["896333d916d247f3"] = { "È mio...", "." },
  ["8965394305f1b4af"] = { "Bene, io vado dai Gelkis. Non sono stupidi come i Maraudine, ma sono più ragionevoli.", "." },
  ["896733b4204741ab"] = { "Impotente... senza forze... ripristinare... devo ripristinare... Zevrim controlla... porre fine a questo tormento...", "." },
  ["8968a5a8074c396d"] = { "Sono \"Plucky\" Johnson, e questo è il mio saluto predefinito.", "." },
  ["89691ed71003eb11"] = { "Dunque hai portato la torcia. Sì, giovane {class}, posso insegnarti a rispondere al richiamo del fuoco. Non sarà facile, ma niente di ciò che facciamo in questo regno è mai facile.", "." },
  ["8969925def5635df"] = { "Proprio così. Muori come il cane che sei.", "." },
  ["8969aa5bcc6c0e93"] = { "Forze antiche si risvegliano, forze che non si vedevano né si sentivano da migliaia di anni. Il mondo piange, {race}. Forse si avvicina una nuova frattura del mondo. Un male nato dall'interno...\n\nLa corruzione ha cominciato a infiltrarsi nelle nostre terre. Dal Sogno nascono incubi. Incubi che ci contaminano nelle ore di veglia...", "." },
  ["896a46392f021336"] = { "Non così in fretta, <giovanotto/signorina>... Non affiderò le redini di un possente montone a qualcuno che non sia un alleato provato dei nani di ⟦Ironforge=Forgiardente⟧. Quando avrai raggiunto il livello Osannato con ⟦Ironforge=Forgiardente⟧, ti mostrerò volentieri le varietà di montoni che ho in vendita.", "." },
  ["8973bbd16910d3b7"] = { "Puoi cercare Martin Lindsey dentro le Pozze delle Visioni, sotto l'⟦Spirit Rise=Altura degli Spiriti⟧. Ti aiuterà a raggiungere il ⟦Arathi Basin=Bacino d'Arathi⟧.", "." },
  ["897578835646e25d"] = { "Andrei io a fare piazza pulita di un po' di quegli gnoll, ma questa gamba ha visto giorni migliori e temo che finirei solo per lasciarci la pelle.", "." },
  ["8977c8b092173d22"] = { "Aspetta, ⟦Gadgetzan=Meccania⟧ ha una discoteca?", "." },
  ["898004aebd77ec0f"] = { "Dun Baldar è la roccaforte più potente dell'⟦Alliance=Alleanza⟧ nella ⟦Alterac Valley=Valle d'Alterac⟧. Annidata nelle propaggini settentrionali della valle, Dun Baldar è la base di partenza di tutte le avanzate verso sud.\n\nDun Baldar è stata rasa al suolo ed è in ricostruzione.", "." },
  ["8986520d98b206e4"] = { "La figura spettrale ti guarda con diffidenza negli occhi e resta in silenzio.", "." },
  ["8996f27637f56dfe"] = { "Ma perché dobbiamo imparare questa roba?", "." },
  ["899d34cc20504cee"] = { "Kalaran, ho perso la mia torcia. Me ne serve un'altra.", "." },
  ["89a1e1ebe49b1e3a"] = { "Di certo non mi hai deluso! Ora che abbiamo sistemato questa faccenda, il tuo addestramento può cominciare!", "." },
  ["89ae5d9f76ced539"] = { "Hai trovato una chiave? Beh, è LA chiave? Voglio dire, è la chiave che apre queste catene? Beh, <signore/signora>, c'è un solo modo per scoprirlo!", "." },
  ["89b95459236de7b6"] = { "Ho trovato la morte cento volte. Mi risveglio sempre qui, in vita. C'è chi dice che su di me grava una maledizione, e altri...", "." },
  ["89c8ed65f223115d"] = { "%s attacca la picca!", "." },
  ["89d607361334b1c9"] = { "Quante bende ha raccolto finora l'⟦Horde=Orda⟧?", "." },
  ["89d65290f61289b9"] = { "Ciao. Sono Gubber Blump.", "." },
  ["89da26d4917f0b80"] = { "Non fare alcun rumore durante il rituale. Un solo passo falso potrebbe segnare la nostra rovina...", "." },
  ["89df9e8de9968157"] = { "Cerca in giro per Old Town, alla caserma o alla Pig and Whistle Tavern. Se vai alla taverna, assaggia senz'altro qualcuna delle sue ottime birre. Fanno sfigurare quelle dei nani, te lo dico io.", "." },
  ["89e0bdcca491cf48"] = { "Non temere. I Guardiani della Notte libereranno presto la terra da questa sozza corruzione.", "." },
  ["89e52da8df5c6eeb"] = { "Dove caddero i due amanti sarebbe sbocciato un albero. Gli elfi lo chiamano heartswood. Di certo servirà ai tuoi scopi.", "." },
  ["89ea302d1d1395f4"] = { "<Omarion borbotta qualcosa sottovoce.>\n\nMa certo che posso aiutarti, <caro/cara> <ragazzo/ragazza>. È il mio ultimo desiderio... la mia ultima volontà. Ti prego, prendi questo manuale. Le sue pagine raccolgono tutto ciò che so e che ho imparato negli ultimi 30 e passa anni della mia misera vita. Consegna il manuale a quel buono a nulla del mio apprendista, che probabilmente se ne sta seduto sul suo grasso deretano alla ⟦Light's Hope Chapel=Cappella della Luce⟧.", "." },
  ["89eb0bbc0658b3e0"] = { "Per quanto l'erba fresca che ricopre Teldrassil sia per me un letto come un altro, i letti che Saelienne tiene alla locanda della Terrazza degli Artigiani sono decisamente adatti a chi ha un debole per il lusso.", "." },
  ["89edb16e93002123"] = { "Credo proprio che dovrò fare qualcosa al riguardo!", "." },
  ["89f37217f09cb1b0"] = { "Signora insegna a te fare oggetti magici. Lei sta in anello interno di The Apothecarium.", "." },
  ["89f51d47ff4fb16a"] = { "Ehi, <cittadino/cittadina>! Hai un'aria robusta. Noi guardie qui fuori siamo un po' a corto di forze, e un aiuto mi farebbe comodo...", "." },
  ["89f7a82db3fb380a"] = { "Prima di poter rispondere correttamente a questa domanda, devi ricevere ulteriori informazioni di base sui Terrigeni.\n\nElaborazione in corso.\n\nPer comprendere le anomalie dei Terrigeni, è innanzitutto importante comprendere ciò che i Terrigeni rappresentano nell'intento progettuale. I Terrigeni rappresentano il tentativo dei Creatori di migliorare il paradigma di sopravvivenza della matrice standard dell'essere sotterraneo. Ciò fu ottenuto incorporando in tale matrice un fondamento costruttivo resiliente, intrinseco al mondo.", "." },
  ["89fa93a6389feeba"] = { "OK capo, quando tu pronto per tributo da tuoi scagnozzi, tu fammi sapere!", "." },
  ["89fb1b0f7b68f0ee"] = { "Horgus, il tuo incubo finisce! Ora!", "." },
})
